import{_ as o,o as t,c as a,a0 as r}from"./chunks/framework.jwovEGr5.js";const u=JSON.parse('{"title":"ADR 0001 — No mobile app","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-no-mobile-app.md","filePath":"adr/0001-no-mobile-app.md"}'),i={name:"adr/0001-no-mobile-app.md"};function s(n,e,d,l,c,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0001-—-no-mobile-app" tabindex="-1">ADR 0001 — No mobile app <a class="header-anchor" href="#adr-0001-—-no-mobile-app" aria-label="Permalink to &quot;ADR 0001 — No mobile app&quot;">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-07-10</li><li><strong>Deciders:</strong> sharecli maintainers</li><li><strong>Tags:</strong> packaging, distribution, L117</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Cluster C11 (packaging / distribution) asks whether sharecli should ship a mobile presence (native iOS/Android, Expo, or PWA). The product is a <strong>local process supervisor and CLI toolkit</strong>: it watches TOML configs, spawns OS processes, exposes a loopback HTTP API (<code>/healthz</code>, <code>/readyz</code>, metrics), and optionally a desktop tray. Operators run it on developer workstations and fleet hosts — not on phones.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>No mobile app, PWA, or responsive mobile web client.</strong> Mobile is out of scope for sharecli.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Score L117 as a deliberate &quot;no mobile, here&#39;s why&quot; (not an unconsidered gap).</li><li>Do not add Expo/React Native, Capacitor, or a service-worker PWA to this repo.</li><li>Remote visibility, if needed later, belongs in a separate ops dashboard or fleet coordinator — not a phone-native shell around the supervisor.</li><li>Revisit only if the product pivots to a hosted multi-tenant control plane with a first-class mobile operator UX.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Why rejected</th></tr></thead><tbody><tr><td>Native iOS/Android</td><td>No process-spawn surface on mobile; App Store sandbox cannot host the supervisor model</td></tr><tr><td>Expo / React Native companion</td><td>Would duplicate the HTTP API without adding install/run value for the CLI</td></tr><tr><td>PWA wrapping <code>/</code> dashboard</td><td>Dashboard is localhost-bound; a PWA adds little over a browser bookmark</td></tr><tr><td>&quot;Undecided / later&quot;</td><td>Leaves L117 unscored; operator asked for an explicit answer</td></tr></tbody></table>',10)])])}const b=o(i,[["render",s]]);export{u as __pageData,b as default};
